INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — GASB 87 lease: fund-level vs government-wide treatment
(2, 'Governmental Accounting', 'The City of Redford enters a 7-year office lease on July 1, 2026, with annual payments of $95,000. The finance director records the lease in the general fund. Under GASB 87, how does recording this lease differ between the governmental fund statements and the government-wide statements?', '["Both statements recognize a lease liability and a right-of-use intangible asset at the present value of lease payments", "The governmental fund capitalizes the right-of-use asset while the government-wide statements record only annual expenditures", "The governmental fund reports annual lease expenditures while the government-wide statements recognize a lease liability and intangible right-of-use asset", "Neither set of statements capitalizes the lease because governmental leases are exempt from GASB 87"]'::jsonb, 2, 'Under GASB 87, lessees recognize a lease liability and an intangible right-of-use asset in the government-wide financial statements because these use the economic resources measurement focus and accrual basis. However, governmental funds use the current financial resources measurement focus, so they report only lease expenditures as payments come due. Choice A is incorrect because governmental fund statements do not recognize long-term lease liabilities or intangible assets under the current financial resources measurement focus.', 'medium', 3),

-- Q2: medium / L3 — Derived tax revenue recognition timing
(2, 'Governmental Accounting', 'Oakdale County collects a local income tax surcharge, receiving $4.2 million during fiscal year 2026 plus an additional $380,000 in January 2027 for income earned in 2026. The county''s availability period is 60 days. How does the classification of income tax as a derived tax revenue under GASB 33 affect the general fund revenue amount?', '["Revenue is recognized only when cash is collected during the fiscal year, limiting recognition to $4,200,000", "Revenue is recognized when the underlying exchange transaction occurs and the revenue is available, so the $380,000 collected in January qualifies if received within the 60-day availability period", "Revenue is deferred entirely until the individual tax returns are filed and assessed by the taxing authority", "Revenue is recognized on the government-wide statements only, with no recognition permitted in governmental funds until cash is received"]'::jsonb, 1, 'Under GASB 33, derived tax revenues such as income taxes are recognized when the underlying exchange transaction occurs and the resources are available. Because the $380,000 relates to income earned during 2026 and is collected within the 60-day availability period, it qualifies for recognition in the general fund. Choice A is incorrect because modified accrual does not require cash collection during the fiscal year—it requires collection within the availability period after year-end.', 'medium', 3),

-- Q3: hard / L4 — GASB 96 SBITA vs GASB 87 lease evaluation
(2, 'Governmental Accounting', 'The City of Weston signs a 5-year contract on January 1, 2027, to use a cloud-based enterprise resource planning system for $180,000 annually. The city does not take possession of hardware; all processing occurs on the vendor''s servers. The IT director argues this is a service contract, while the finance director believes it meets GASB 96''s criteria for a subscription-based IT arrangement. Evaluate the most appropriate accounting treatment.', '["Record as a service contract with annual expenditures because the city never takes possession of tangible assets", "Capitalize as a leased asset under GASB 87 because the contract conveys control of an identified IT asset for a specified term", "Record as a capital asset purchase because the arrangement provides ongoing access to the software platform", "Recognize a subscription liability and right-to-use subscription asset under GASB 96 because the contract conveys control of the right to use another party''s IT software for a specified term"]'::jsonb, 3, 'Under GASB 96, a subscription-based IT arrangement (SBITA) that conveys control of the right to use another party''s IT software for a period of time requires recognition of a subscription liability and an intangible right-to-use asset. This standard is distinct from GASB 87, which applies to non-IT underlying assets. Choice A is incorrect because GASB 96 specifically requires capitalization of qualifying IT subscription arrangements rather than treating them as period expenses, provided the arrangement meets the SBITA definition.', 'hard', 4),

-- Q4: easy / L1 — Special revenue fund definition
(2, 'Governmental Accounting', 'Under GASB standards, what is the primary purpose of a special revenue fund?', '["To account for revenues that are restricted or committed to expenditures for specific purposes other than debt service or capital projects", "To account for all general operating revenues and expenditures of the government", "To account for resources held in trust for the benefit of external parties", "To account for goods and services provided by one government department to another on a cost-reimbursement basis"]'::jsonb, 0, 'Under GASB 54, a special revenue fund accounts for the proceeds of specific revenue sources that are restricted or committed to expenditures for specified purposes other than debt service or capital projects. Choice B is incorrect because it describes the general fund, not a special revenue fund. Special revenue funds must have a substantial revenue source that is restricted or committed to a particular use.', 'easy', 1),

-- Q5: easy / L2 — Deferred inflows from advance property tax levy
(2, 'Governmental Accounting', 'On October 1, 2026, the Town of Millbrook levies $6,500,000 in property taxes for its fiscal year beginning January 1, 2027. By December 31, 2026, the town has collected $1,800,000. How should Millbrook report the $1,800,000 in its general fund at December 31, 2026?', '["Property tax revenue of $1,800,000", "Deferred inflows of resources of $1,800,000", "Unearned revenue of $1,800,000 with an offsetting accounts receivable", "Cash with no revenue or deferred inflow recognized until January 1, 2027"]'::jsonb, 1, 'Under GASB 33 and GASB 65, property taxes levied for a future period are reported as deferred inflows of resources because the resources were received before the period to which they relate. The $1,800,000 collected in advance cannot be recognized as revenue until the fiscal year for which the taxes were levied begins. Choice A is incorrect because revenue cannot be recognized for property taxes levied for a future fiscal period, even though cash has been collected.', 'easy', 2),

-- Q6: easy / L1 — General fund always reported as major fund
(2, 'Governmental Accounting', 'Under GASB 34, which governmental fund is always reported as a major fund regardless of its relative size?', '["The debt service fund with the largest outstanding balance", "The largest special revenue fund by total assets", "The government''s general fund", "The capital projects fund with the highest expenditures"]'::jsonb, 2, 'Under GASB 34, paragraph 76, the general fund is always reported as a major fund regardless of whether it meets the quantitative major fund criteria. All other governmental and enterprise funds must meet both the 10% and 5% thresholds to qualify as major funds unless the government elects to report them as major. Choice A is incorrect because the debt service fund must meet the size thresholds like any other fund to qualify as a major fund.', 'easy', 1),

-- Q7: medium / L2 — Interfund receivables/payables elimination in government-wide
(2, 'Governmental Accounting', 'At fiscal year-end, the City of Glenview reports a $750,000 interfund receivable in the general fund and a corresponding $750,000 interfund payable in the capital projects fund. Both funds are classified as governmental activities. How should these interfund balances be reported on the government-wide statement of net position?', '["Eliminated in full because both funds are within governmental activities", "Reported as internal balances between governmental activities and business-type activities", "Reported as a receivable and payable with note disclosure on the government-wide statements", "Netted against fund balance in each respective fund before converting to the government-wide statements"]'::jsonb, 0, 'Under GASB 34, paragraph 58, interfund receivables and payables between funds within the same activity category (governmental activities) must be eliminated in the government-wide statement of net position. Only balances between governmental activities and business-type activities are reported as internal balances. Choice B is incorrect because internal balances apply only when interfund amounts cross the governmental/business-type divide, not when both funds are within governmental activities.', 'medium', 2),

-- Q8: medium / L3 — Blending vs discrete presentation of component units
(2, 'Governmental Accounting', 'The Greenfield County Public Library has a separately elected board, raises its own revenue through a dedicated property tax levy, and provides services to all county residents. The county''s finance director must determine how to present the library in the county''s financial statements. Under GASB 14 (as amended by GASB 61), which factor most strongly supports discrete presentation rather than blending?', '["The library serves the same geographic area as the primary government", "The library receives a portion of its funding from the county''s general fund transfers", "The county appoints a majority of the library''s governing board members", "The library has a separately elected governing board and does not exclusively serve the primary government entity"]'::jsonb, 3, 'Under GASB 14 (as amended by GASB 61), a component unit is blended only when its governing body is substantively the same as the primary government or when it provides services exclusively or almost exclusively to the primary government. A separately elected governing board indicates the library operates independently, favoring discrete presentation. Choice C is incorrect because board appointment alone does not determine blending—the substantive-sameness or exclusive-service criteria must also be satisfied.', 'medium', 3),

-- Q9: hard / L4 — Capital projects fund close-out residual balance
(2, 'Governmental Accounting', 'The City of Briarwood completed construction of a $12 million civic center using capital projects fund resources from general obligation bond proceeds. After all contracts are paid, a residual balance of $430,000 remains. The city council debates whether to transfer the surplus to the debt service fund for early bond retirement or to the general fund for unrestricted use. The bond covenant is silent on the disposition of excess proceeds. Evaluate the most appropriate disposition.', '["Return the $430,000 to the general fund because the capital projects fund must close with a zero balance after project completion", "Transfer the $430,000 to the debt service fund because bond proceeds should be used for purposes related to the bonds, and early retirement is the most fiscally appropriate use", "Retain the $430,000 in the capital projects fund indefinitely until the next capital project is authorized by the city council", "Distribute the $430,000 proportionally between the general fund and debt service fund based on their relative fund balances"]'::jsonb, 1, 'Under GASB guidance and sound fiscal management principles, when bond covenants are silent, residual bond proceeds from completed capital projects should be directed to the debt service fund for bond retirement. This aligns with the restricted nature of bond proceeds under GASB 54 and the fiduciary purpose for which the bonds were issued. Choice A is incorrect because transferring bond proceeds to the general fund for unrestricted use would conflict with the implicit restriction on debt-financed resources.', 'hard', 4),

-- Q10: medium / L3 — GASB 77 tax abatement disclosure requirements
(2, 'Governmental Accounting', 'The City of Riverton grants a 10-year, 50% property tax abatement to Apex Industries in exchange for constructing a $25 million manufacturing plant and creating 200 jobs. The annual foregone revenue is $310,000. Under GASB 77, how does this tax abatement arrangement affect the city''s financial reporting?', '["The city must recognize a liability for the total foregone revenue over the 10-year abatement period", "The city records the abatement as an expenditure equal to the annual foregone revenue of $310,000", "The city must disclose the abatement program, including the purpose, the taxes being abated, and the dollar amount of taxes foregone during the reporting period", "No financial statement impact is required because the taxes were never levied on the abated portion of the assessed value"]'::jsonb, 2, 'Under GASB 77, governments must disclose tax abatement agreements that reduce tax revenues, including the tax being abated, the authority under which the abatement is granted, eligibility criteria, the mechanism, and the dollar amount of taxes foregone during the period. GASB 77 requires note disclosure rather than liability recognition or expenditure recording. Choice D is incorrect because GASB 77 specifically mandates disclosure even though the foregone revenue does not appear as a line item on the face of the financial statements.', 'medium', 3),

-- Q11: hard / L3 — Major fund criteria dual threshold test calculation
(2, 'Governmental Accounting', 'A county government has total governmental fund assets of $180 million and total enterprise fund assets of $120 million. The parks special revenue fund reports total assets of $22 million. The finance director applies the GASB 34 major fund criteria using the total assets element. What is the result of applying the dual threshold test to determine whether the parks fund is a major fund?', '["The parks fund qualifies as major because its $22 million exceeds both 10% of $180 million in governmental fund assets and 5% of $300 million in combined governmental and enterprise fund assets", "The parks fund does not qualify because its assets are less than 10% of the $300 million combined governmental and enterprise fund total", "The parks fund qualifies based on meeting only the 5% threshold without needing to satisfy the 10% threshold", "The parks fund cannot be classified as major because special revenue funds are excluded from the dual threshold test"]'::jsonb, 0, 'Under GASB 34, paragraph 76, a governmental fund qualifies as major if any single financial element is at least 10% of the corresponding total for all governmental funds AND at least 5% of the combined total for all governmental and enterprise funds. The parks fund''s $22 million is 12.2% of $180 million (exceeds 10%) and 7.3% of $300 million (exceeds 5%), satisfying both thresholds. Choice B is incorrect because the 10% test compares to governmental funds only, not the combined total.', 'hard', 3),

-- Q12: medium / L2 — Infrastructure capitalization under depreciation approach
(2, 'Governmental Accounting', 'The City of Hartwell constructs a new bridge costing $8.4 million in 2026. The city''s capitalization threshold for infrastructure is $500,000, and it uses the depreciation approach under GASB 34 with an estimated useful life of 40 years. How should the bridge be reported in the government-wide statements?', '["Expensed in full in the year of construction because infrastructure assets are not capitalized under governmental accounting", "Recorded as an expenditure in the capital projects fund with no capitalization in the government-wide statements", "Capitalized and depreciated only if the bridge has a determinable useful life of less than 20 years", "Capitalized as an infrastructure asset at $8,400,000 and depreciated over its 40-year estimated useful life"]'::jsonb, 3, 'Under GASB 34, paragraphs 18-22, infrastructure assets that exceed the government''s capitalization threshold must be reported in the government-wide statement of net position. When using the depreciation approach, the asset is depreciated over its estimated useful life. The bridge''s $8.4 million cost exceeds the $500,000 threshold and must be capitalized. Choice A is incorrect because GASB 34 explicitly requires capitalization of infrastructure assets in government-wide statements.', 'medium', 2),

-- Q13: easy / L1 — Nonspendable fund balance
(2, 'Governmental Accounting', 'Under GASB 54, which category of fund balance represents amounts that cannot be spent because of their form?', '["Restricted fund balance", "Nonspendable fund balance", "Committed fund balance", "Assigned fund balance"]'::jsonb, 1, 'Under GASB 54, paragraph 6, nonspendable fund balance includes amounts not in spendable form (such as inventories and prepaid items) or amounts legally or contractually required to remain intact (such as the corpus of a permanent fund). Choice A is incorrect because restricted fund balance refers to amounts constrained by external parties, legislation, or enabling legislation—not by the physical form of the resource itself.', 'easy', 1),

-- Q14: hard / L4 — Agent multiple-employer pension plan reporting
(2, 'Governmental Accounting', 'The City of Pinehurst participates in an agent multiple-employer defined benefit pension plan administered by the state retirement system. The actuary reports a total pension liability of $48 million and plan net position of $31 million for Pinehurst''s portion. The finance director proposes reporting only the city''s annual required contribution as pension expense on the government-wide statements. The auditor disagrees. Evaluate the correct reporting under GASB 68.', '["The finance director is correct because agent plan employers report only their annual contributions as pension expense", "The auditor should accept the finance director''s approach because the state retirement system reports the net pension liability on behalf of all participating employers", "The auditor is correct because the city must report a net pension liability of $17 million and recognize pension expense that includes service cost, interest, and changes in deferred outflows and inflows", "The city should report only a note disclosure of the unfunded liability because the pension plan is administered by a separate legal entity"]'::jsonb, 2, 'Under GASB 68, paragraphs 28-36, employers in agent multiple-employer plans must recognize their individual net pension liability on the government-wide financial statements. Pension expense includes service cost, interest on total pension liability, projected earnings on plan assets, and amortization of deferred outflows and inflows. The net pension liability is $48 million minus $31 million, or $17 million. Choice A is incorrect because GASB 68 replaced the contribution-based approach with a liability-based model requiring full net pension liability recognition.', 'hard', 4),

-- Q15: easy / L1 — MD&A as required supplementary information
(2, 'Governmental Accounting', 'Under GASB 34, where is management''s discussion and analysis presented in a government''s financial report?', '["As a footnote to the financial statements", "As supplementary information following the notes to the financial statements", "As a component of the basic financial statements between the fund and government-wide statements", "As required supplementary information preceding the basic financial statements"]'::jsonb, 3, 'Under GASB 34, paragraph 8, management''s discussion and analysis is required supplementary information (RSI) that precedes the basic financial statements. MD&A provides an analytical overview of the government''s financial activities based on currently known facts and conditions. Choice C is incorrect because MD&A is not part of the basic financial statements themselves—it is RSI that introduces and explains the financial statements to readers.', 'easy', 1),

-- Q16: medium / L3 — Special items on statement of activities
(2, 'Governmental Accounting', 'The City of Dunmore sells its municipal golf course for $3.8 million, resulting in a $1.2 million gain. The sale was approved by the city council as part of a strategic divestiture plan and was a one-time occurrence. Under GASB 34, how does reporting this transaction as a special item affect its placement on the statement of activities?', '["A special item is reported separately after general revenues and before the change in net position, providing visibility into its unusual and infrequent nature", "A special item is netted against program expenses to reduce the reported net cost of the recreation function", "A special item is excluded from the statement of activities and reported only in the notes to the financial statements", "A special item is reported as a program revenue under the function that operated the golf course"]'::jsonb, 0, 'Under GASB 34, paragraph 56, special items are significant transactions within management''s control that are either unusual or infrequent. They are reported separately in the statement of activities after general revenues and before the change in net position, drawing attention to their non-recurring nature. Choice D is incorrect because special items are not classified as program revenues—they are reported as a distinct line item to distinguish them from normal recurring activities.', 'medium', 3),

-- Q17: medium / L2 — Charges for services as program revenue
(2, 'Governmental Accounting', 'The City of Eastbrook operates a public swimming pool in the general fund, charging admission fees that generate $1,950,000 annually. The pool''s total operating costs of $2,780,000 are subsidized by property tax revenues. On the government-wide statement of activities, how should the $1,950,000 in admission fee revenue be classified?', '["General revenue because the fees are collected from the general public", "Charges for services reported as program revenue offsetting the recreation function''s expenses", "Miscellaneous revenue reported below general revenues on the statement of activities", "An interfund transfer because the fees partially support a tax-subsidized governmental activity"]'::jsonb, 1, 'Under GASB 34, paragraph 48, charges for services include revenues from exchange or exchange-like transactions and are classified as program revenues on the statement of activities. Admission fees charged by a swimming pool directly relate to the recreation function and offset that function''s expenses when calculating net expense. Choice A is incorrect because charges for services are program revenues, not general revenues—property taxes and unrestricted grants are examples of general revenues.', 'medium', 2),

-- Q18: medium / L3 — Deferred outflows from pension contribution after measurement date
(2, 'Governmental Accounting', 'The City of Haverford makes a $2.1 million employer pension contribution on June 15, 2026, for its fiscal year ending June 30, 2026. The pension plan''s measurement date is December 31, 2025. Under GASB 68, the contribution falls after the measurement date but before the reporting date. How does this timing difference affect the government-wide financial statements?', '["The $2.1 million is recognized as pension expense for the fiscal year ended June 30, 2026", "The $2.1 million directly reduces the net pension liability as of the June 30, 2026, reporting date", "The $2.1 million is reported as a deferred outflow of resources in the government-wide statement of net position", "The $2.1 million is excluded from the June 30, 2026, financial statements and disclosed only in the notes"]'::jsonb, 2, 'Under GASB 68, paragraph 57, employer contributions made after the measurement date of the net pension liability but before the end of the reporting period are reported as deferred outflows of resources. These amounts will reduce the net pension liability in the subsequent measurement period. Choice A is incorrect because contributions made after the measurement date cannot be recognized as pension expense in the current period—they must first be classified as deferred outflows.', 'medium', 3),

-- Q19: easy / L1 — Committed fund balance authority level
(2, 'Governmental Accounting', 'Under GASB 54, what level of authority is required to establish a committed fund balance?', '["The government''s highest level of decision-making authority through formal action before fiscal year-end", "The finance director through an administrative policy memorandum", "The department head responsible for the affected fund''s operations", "Any elected official with budgetary approval authority over the fund"]'::jsonb, 0, 'Under GASB 54, paragraph 10, committed fund balance requires formal action by the government''s highest level of decision-making authority (typically the governing body, such as a city council or county board). The commitment must be made before fiscal year-end and can only be removed by the same authority through the same type of formal action. Choice B is incorrect because administrative officials cannot establish committed fund balance—that authority is reserved for the governing body.', 'easy', 1),

-- Q20: hard / L4 — Internal service fund markup elimination in government-wide
(2, 'Governmental Accounting', 'The City of Thornburg''s internal service fund provides fleet maintenance to all city departments, charging a 15% markup over actual costs. During fiscal year 2026, the fund bills $4,600,000 to governmental activity departments and $920,000 to the water enterprise fund. Total actual costs are $4,800,000. The finance director must prepare the government-wide statements. Evaluate the appropriate treatment of the internal service fund''s charges and operating results.', '["Report the internal service fund as a separate business-type activity because it charges fees for services", "Eliminate all internal service fund transactions and allocate the $4,800,000 in costs equally across governmental and business-type activities", "Report the internal service fund revenues and expenses at full billed amounts within governmental activities with no elimination", "Consolidate the internal service fund predominantly into governmental activities, eliminate the markup charged to governmental departments, and report the $920,000 enterprise fund charge as an internal balance"]'::jsonb, 3, 'Under GASB 34, paragraphs 62-63, internal service funds are typically reported within governmental activities because their predominant customers are usually governmental funds. The markup charged to governmental departments must be eliminated to avoid double-counting, while charges to enterprise funds create internal balances between governmental and business-type activities. Choice A is incorrect because internal service funds are not reported as separate business-type activities—they are consolidated into the activity category of their predominant customers.', 'hard', 4),

-- Q21: easy / L1 — Budgetary comparison schedule requirement
(2, 'Governmental Accounting', 'Under GASB 34, which funds require a budgetary comparison schedule or statement as required supplementary information?', '["All enterprise funds that have legally adopted operating budgets", "All capital projects funds regardless of whether a budget was legally adopted", "The general fund and each major special revenue fund with a legally adopted annual budget", "Only the debt service fund when outstanding general obligation bonds exceed $5 million"]'::jsonb, 2, 'Under GASB 34, paragraph 130, governments must present budgetary comparison schedules for the general fund and each major special revenue fund that has a legally adopted annual budget. The comparison shows original budget, final budget, and actual amounts on the budgetary basis. Choice A is incorrect because enterprise funds are proprietary funds and are not required to present budgetary comparisons as RSI, even if they have legally adopted budgets.', 'easy', 1),

-- Q22: hard / L4 — GASB 87 short-term lease exemption evaluation
(2, 'Governmental Accounting', 'The City of Palmdale enters a 2-year copier lease on January 1, 2027, with monthly payments of $1,200 and an option to extend for three additional years at the same rate. The city''s IT manager determines the extension is reasonably certain to be exercised based on the department''s equipment plan. The IT manager argues the lease qualifies for GASB 87''s short-term exemption because the initial noncancellable term is only 2 years. Evaluate whether the exemption applies.', '["The short-term exemption does not apply because the maximum possible term, including the reasonably certain extension, is 5 years, which exceeds the 12-month threshold", "The short-term exemption applies because the initial noncancellable period of 2 years determines the lease term for exemption purposes", "The short-term exemption applies because copier leases are classified as immaterial equipment leases excluded from GASB 87", "The short-term exemption does not apply because GASB 87 eliminated all short-term lease exemptions for governmental entities"]'::jsonb, 0, 'Under GASB 87, paragraph 16, a short-term lease has a maximum possible term of 12 months or less, including any options to extend that are reasonably certain to be exercised. Because the 3-year extension is reasonably certain, the total lease term is 5 years, far exceeding the 12-month threshold. The city must recognize a lease liability and intangible right-to-use asset. Choice B is incorrect because GASB 87 includes extension options that are reasonably certain when determining the maximum possible term.', 'hard', 4),

-- Q23: medium / L2 — Capital contributions in enterprise funds
(2, 'Governmental Accounting', 'The City of Waverly''s water enterprise fund receives a $1.6 million infrastructure contribution from Cedarbrook Development LLC, which installs water mains as a condition of subdivision approval. The infrastructure is dedicated to the city upon completion. Under GASB 34, how should the enterprise fund report this contribution?', '["Operating revenue in the enterprise fund''s statement of revenues, expenses, and changes in net position", "Capital contribution reported separately below nonoperating revenues and expenses", "A reduction of infrastructure construction costs rather than a revenue or contribution item", "A deferred inflow of resources amortized over the useful life of the contributed water mains"]'::jsonb, 1, 'Under GASB 34, paragraph 100, capital contributions from developers and other external sources are reported separately after nonoperating revenues and expenses on the proprietary fund statement of revenues, expenses, and changes in net position. The infrastructure is capitalized at fair value. Choice A is incorrect because capital contributions are not operating revenues—operating revenues arise from the fund''s principal ongoing operations, such as charges for water service.', 'medium', 2),

-- Q24: easy / L1 — Proprietary fund measurement focus
(2, 'Governmental Accounting', 'Under GASB standards, what measurement focus is used for proprietary fund financial statements?', '["Current financial resources measurement focus", "Modified accrual measurement focus", "Cash basis measurement focus", "Economic resources measurement focus"]'::jsonb, 3, 'Under GASB 34, proprietary funds (enterprise funds and internal service funds) use the economic resources measurement focus combined with the accrual basis of accounting. This means all assets, deferred outflows, liabilities, deferred inflows, revenues, and expenses are recognized regardless of when cash is received or paid. Choice A is incorrect because the current financial resources measurement focus is used by governmental funds, not proprietary funds.', 'easy', 1),

-- Q25: medium / L2 — Fund balance spending order under GASB 54
(2, 'Governmental Accounting', 'The City of Ferndale''s general fund has the following fund balance components: $800,000 restricted for public safety, $500,000 committed for parks improvements, $300,000 assigned for vehicle replacement, and $1,200,000 unassigned. The city has no formal spending policy. The city incurs $600,000 of qualifying public safety expenditures. Under GASB 54, which resources are considered spent first?', '["Restricted resources are spent first, reducing the restricted public safety balance from $800,000 to $200,000", "Unassigned resources are spent first to preserve restricted and committed balances for future use", "The $600,000 is split proportionally across all four fund balance categories based on their relative amounts", "Committed resources are spent first because they represent the highest level of internal constraint"]'::jsonb, 0, 'Under GASB 54, paragraph 18, when both restricted and unrestricted resources are available for an expenditure, restricted resources are considered spent first. When unrestricted resources are subsequently used, the default order is committed, assigned, then unassigned—unless the government establishes a different policy. Choice B is incorrect because GASB 54 presumes that the most constrained resources (restricted) are consumed before less constrained resources.', 'medium', 2),

-- Q26: medium / L2 — Financial accountability and component unit determination
(2, 'Governmental Accounting', 'Maple County appoints a majority of the board members of the Maple County Land Trust, a legally separate entity. The county can impose its will on the trust''s operations, and the trust provides a direct financial benefit to the county. Under GASB 14 (as amended by GASB 61), which criterion establishes financial accountability over the trust?', '["The trust operates within the same geographic boundary as the primary government", "The trust receives any amount of operational funding from the county''s general fund", "The county appoints a voting majority of the trust''s board and either can impose its will or receives a financial benefit or burden", "The trust was created by the county''s enabling legislation and has a June 30 fiscal year-end"]'::jsonb, 2, 'Under GASB 14, paragraph 21 (as amended by GASB 61), financial accountability exists when the primary government appoints a voting majority of the component unit''s governing board and either can impose its will on the entity or there is a potential for financial benefit or burden. Both conditions—board appointment and benefit/burden or imposition of will—must be present. Choice D is incorrect because creation through enabling legislation alone does not establish financial accountability without board appointment and the ability to impose will or receive benefit/burden.', 'medium', 2),

-- Q27: medium / L2 — Government-mandated nonexchange transaction under GASB 33
(2, 'Governmental Accounting', 'The state government mandates that Ridgewood County provide after-school tutoring programs and awards a $2.8 million grant to fund the mandate. The grant specifies that funds may be spent only on allowable tutoring costs. Under GASB 33, how should the county classify and recognize this grant revenue?', '["As a voluntary nonexchange transaction recognized when all eligibility requirements are met", "As an exchange transaction recognized proportionally as tutoring services are delivered to students", "As a derived tax revenue recognized when the underlying exchange transaction occurs", "As a government-mandated nonexchange transaction recognized when all eligibility requirements are met and the resources are available"]'::jsonb, 3, 'Under GASB 33, paragraph 19, government-mandated nonexchange transactions occur when a higher-level government requires a lower-level government to perform a specific activity and provides funding. Revenue is recognized when all eligibility requirements (including allowable cost provisions) are met and, for governmental funds, the resources are available. Choice A is incorrect because voluntary nonexchange transactions involve willing participation—here the state mandates the activity, making it a government-mandated transaction.', 'medium', 2),

-- Q28: easy / L1 — Assigned fund balance definition
(2, 'Governmental Accounting', 'Under GASB 54, what does assigned fund balance represent?', '["Resources constrained by external creditors, grantors, or enabling legislation", "Resources intended for a specific purpose as expressed by the governing body or a designated official", "Resources that cannot be spent because they are not in a spendable form", "Resources constrained by the government''s highest level of decision-making authority through formal action"]'::jsonb, 1, 'Under GASB 54, paragraph 13, assigned fund balance represents amounts that a government intends to use for a specific purpose. Assignment can be made by the governing body or by an official delegated that authority. Unlike committed fund balance, formal action by the highest decision-making authority is not required. Choice D is incorrect because it describes committed fund balance, which requires formal action by the governing body rather than merely an expressed intent.', 'easy', 1),

-- Q29: medium / L3 — Conduit debt obligation reporting under GASB 91
(2, 'Governmental Accounting', 'The City of Maplewood issues $15 million in revenue bonds on behalf of Greenfield Memorial Hospital, a private nonprofit. The bonds are payable solely from hospital revenues, and the city has no legal or moral obligation to repay them if the hospital defaults. Under GASB 91, how does the city''s lack of commitment beyond its conduit role affect reporting on the government-wide statements?', '["The city does not recognize a liability because it has no repayment obligation, but must provide note disclosures about the outstanding conduit debt", "The city must recognize the full $15 million as a long-term liability because it is the legal issuer of the bonds", "The city reports the bonds as a contingent liability with a probable likelihood of requiring payment", "The city recognizes a liability equal to the present value of expected default payments based on the hospital''s credit rating"]'::jsonb, 0, 'Under GASB 91, a government that issues conduit debt with no commitment—either moral or legal—beyond the conduit role does not recognize a liability for the outstanding bonds. However, the government must disclose the nature of the conduit arrangement and the aggregate outstanding amount in the notes to the financial statements. Choice B is incorrect because GASB 91 distinguishes between the issuer''s conduit role and its repayment obligation—merely issuing bonds in a conduit capacity does not create a government liability.', 'medium', 3),

-- Q30: medium / L2 — Fund-to-government-wide reconciliation: capital outlays
(2, 'Governmental Accounting', 'The City of Fairview''s general fund reports $5,400,000 in capital outlay expenditures for fiscal year 2026, purchasing equipment and vehicles with an average useful life of 8 years. In preparing the government-wide financial statements, the finance director must adjust for the difference in measurement focus. What reconciliation adjustment is required?', '["Deduct the $5,400,000 from governmental activities because capital outlays are not government-wide expenses", "Add $5,400,000 to government-wide expenses as an additional current-year depreciation charge", "Remove the $5,400,000 expenditure, capitalize the assets in governmental activities, and recognize $675,000 in depreciation expense", "Report the $5,400,000 as both a fund expenditure and a government-wide capital asset with no net adjustment"]'::jsonb, 2, 'Under GASB 34, the reconciliation between governmental fund statements and government-wide statements requires eliminating capital outlay expenditures and capitalizing the assets in governmental activities. Depreciation expense of $675,000 ($5,400,000 divided by 8 years) replaces the full expenditure because the economic resources measurement focus spreads cost over the asset''s useful life. Choice A is incorrect because simply removing the expenditure without adding depreciation would understate expenses in the government-wide statements.', 'medium', 2)
;

COMMIT;
